/// Bring a standalone element of `ink` from one state to another.
// spec-audit: x:ink/2010/main:<context>
// spec-audit: x:powerpoint/2014/inkAction:<actions>
pub(crate) fn patch_root(w: &mut Writer<'_>, el: &Elem, b: Option<&m::Root>, a: &m::Root) -> R {
    match a {
        m::Root::Ink(a) => patch_ink(
            w,
            el,
            match b {
                Some(m::Root::Ink(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::Definitions(a) => patch_definitions(
            w,
            el,
            match b {
                Some(m::Root::Definitions(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::Trace(a) => patch_trace(
            w,
            el,
            match b {
                Some(m::Root::Trace(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::TraceView(a) => patch_trace_view(
            w,
            el,
            match b {
                Some(m::Root::TraceView(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::MsinkContext(a) => patch_msink_ctx_node(
            w,
            el,
            match b {
                Some(m::Root::MsinkContext(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::ActionActions(a) => patch_action_actions(
            w,
            el,
            match b {
                Some(m::Root::ActionActions(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
    }
}
